#### 3.1. Add baseline security middleware

```js
// app.js – hardened version
require('dotenv').config();               // 1️⃣ Load environment variables first
const express = require('express');
const helmet = require('helmet');         // 2️⃣ Secure HTTP headers
const cors   = require('cors');           // 3️⃣ Controlled CORS policy
const rateLimit = require('express-rate-limit'); // 4️⃣ Basic DoS protection
const morgan = require('morgan');         // 5️⃣ Request logging
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// -------------------- Security middleware --------------------
app.use(helmet());                         // sets X‑Content-Type-Options, CSP, HSTS, etc.
app.use(cors({ origin: process.env.CORS_ORIGIN || 'https://my‑trusted‑frontend.com' }));
app.use(express.json());                  // parse JSON bodies (future POST/PUT)
app.use(morgan('combined'));              // Apache‑style logs -> can be piped to a SIEM

// Rate limiting: max 100 requests per 15 min per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// -------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example with input validation (future‑proof)
app.get(
  '/users',
  // No query params now, but we illustrate how you'd validate them:
