## 3️⃣ Consolidated Revised `app.js`

Below is a **minimal yet hardened version** that incorporates the most critical measures (Helmet, CORS, rate limiting, logging, HTTPS redirect, and a protected `/users` endpoint). You can copy‑paste this directly, then add the more advanced JWT/role logic and database integration as your application grows.

```js
// app.js – security‑hardened starter
require('dotenv').config(); // loads .env (add to .gitignore)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const pinoHttp = require('pino-http');
const { expressjwt: jwtMiddleware } = require('express-jwt');

const app = express();

// ---------------------------
// 1. Basic security middleware
// ---------------------------
app.use(helmet());

// CORS – whitelist (adjust as needed)
const whitelist = process.env.CORS_WHITELIST?.split(',') || [];
const corsOptions = {
  origin: (origin, cb) => {
    if (!origin || whitelist.includes(origin)) {
      cb(null, true);
    } else {
      cb(new Error('Not allowed by CORS'));
    }
  },
};
app.use(cors(corsOptions));

// ---------------------------
// 2. Rate limiting
// ---------------------------
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 120,
  message: { error: 'Too many requests, try again later.' },
});
app.use(limiter);

// ---------------------------
// 3. Logging (pino)
// ---------------------------
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
app.use(pinoHttp({ logger }));

// ---------------------------
// 4. Body parsing (needed for future POST routes)
// ---------------------------
app.use(express.json());

// ---------------------------
// 5. HTTPS enforcement (production only)
// ---------------------------
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}

// ---------------------------
// 6. Authentication placeholder
// ---------------------------
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_IN_PROD';
const auth = jwtMiddleware({ secret: JWT_SECRET, algorithms: ['HS256'] });
const requireAdmin = (req, res, next) => {
  if (req.auth?.role === 'admin') return next();
  return res.status(403).json({ error: 'Forbidden' });
};

// ---------------------------
// 7. Routes
// ---------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example protected endpoint – returns only non‑sensitive data
app.get('/users', auth, requireAdmin, (req, res) => {
  // In production: fetch from DB & omit e‑mail/PII
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ---------------------------
// 8. Global error handler
// ---------------------------
app.use((err, req, res, next) => {
  logger.error({ err, url: req.originalUrl, method: req.method }, 'Unhandled error');
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

module.exports = app;
```

**Next steps**

1. **Add a real login route** that validates passwords with `bcrypt`/`argon2` and issues JWTs containing a `role` claim.
2. **Replace the static user list** with a database query that uses **parameterised statements** (e.g., Prisma or Knex).
3. **Write integration tests** that attempt common attacks (SQLi, XSS, CSRF) to verify your defenses.
4. **Deploy behind an HTTPS‑terminating reverse proxy** (NGINX, Traefik) and ensure the proxy forwards the correct `X‑Forwarded‑Proto` header.
5. **Enable CI security checks** (`npm audit`, `eslint-plugin-security`, Dependabot).

