const express = require('express');
const helmet = require('helmet');           // Secure HTTP headers (A5)
const rateLimit = require('express-rate-limit'); // Basic DoS protection (A5)
const cors = require('cors');               // Control cross‑origin access (A5)
const morgan = require('morgan');           // Request logging (A9)
