## Recommendations & Sample Code

Below is a **security‑hardened rewrite** of `app.js`.  Each change is accompanied by a short explanation.

### 1. Use environment‑driven configuration & sane defaults
```js
// app.js
require('dotenv').config();      // Load .env in development
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');   // For auth (optional, see later)

const app = express();

// ---- Global Middleware -------------------------------------------------
app.use(helmet());               // Sets a robust set of security headers
app.use(cors({                   // Restrict origins to trusted domains
  origin: process.env.CORS_ORIGIN || '*', // change '*' to your UI domain
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json({ limit: '10kb' })); // Body size limit

// ---- Rate Limiting (prevent DoS) ---------------------------------------
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000,   // 1 minute
  max: 100,                  // max 100 requests per IP per minute
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---- Simple request logger (optional but good for audit) ---------------
app.use((req, res, next) => {
  console.info(`[${new Date().toISOString()}] ${req.ip} ${req.method} ${req.originalUrl}`);
  next();
});

// ---- Authentication middleware (protect /users) -----------------------
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }
  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;   // attach user info for downstream use
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// ---- Routes ------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Protected endpoint – only authenticated users can retrieve the list.
 * If you need fine‑grained RBAC, add a role check here.
 */
app.get('/users', authenticate, (req, res) => {
  // In a real app this data would come from a DB with proper access controls.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---- Centralized error handler (no stack traces in prod) ----------------
app.use((err, req, res, next) => {
  console.error(err);        // Log full error for developers
  const status = err.status || 500;
  const message = (process.env.NODE_ENV === 'production')
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

// ---- Server start -------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

