## Specific Code‑Level Recommendations

Below is an **enhanced version of `app.js`** that addresses the most critical findings while keeping the original functionality.

```js
// app.js
// Security‑hardened Express application

require('dotenv').config(); // <-- loads .env (e.g., PORT, JWT_SECRET)

const express = require('express');
const helmet = require('helmet');               // security headers
const cors = require('cors');                   // controlled CORS
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');               // request logging
const jwt = require('jsonwebtoken');            // example auth
const { body, validationResult } = require('express-validator'); // input validation

const app = express();

// ---------- Middleware ----------
app.use(express.json());                // parse JSON bodies
app.use(helmet());                      // sets X‑* headers + CSP defaults
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://my‑frontend.example.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(morgan('combined'));            // logs to stdout (pipe to file in prod)

// Rate limiting – 100 req / 15 min per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Simple auth middleware ----------
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing token' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // attach user info for downstream handlers
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * Example protected endpoint.
 * In a real app you'd fetch this data from a DB with a parameterised query.
 */
app.get('/users', authenticate, (req, res) => {
  // Dummy data – in production pull from DB with proper RBAC checks
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/**
 * Example login endpoint (illustrates input validation and safe password handling).
 */
app.post(
  '/login',
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }).trim(),
  ],
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty())
      return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    // TODO: fetch user from DB, compare hashed password with bcrypt.compare()
    // For demo, assume a static user:
    if (email === 'alice@example.com' && password === 'superSecret123') {
      const token = jwt.sign({ sub: 1, role: 'admin' }, process.env.JWT_SECRET, {
        expiresIn: '1h',
      });
      return res.json({ token });
    }
    return res.status(401).json({ error: 'Invalid credentials' });
  }
);

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
  console.error(err); // log server‑side
  const status = err.status || 500;
  // Do **not** leak stack trace in production
  const response = {
    error: err.message || 'Internal Server Error',
  };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What Changed & Why

| Change | Why it matters |
|--------|----------------|
| `dotenv` + `process.env.PORT` | Avoid hard‑coded values; easier to manage per‑environment configs. |
| `helmet()` | Sets security‑related HTTP headers (Content‑Security‑Policy, X‑Frame‑Options, HSTS, etc.). |
| `cors()` with whitelist | Prevents arbitrary origins from consuming the API. |
| `express-rate-limit` | Mitigates brute‑force, credential‑stuffing, and DoS. |
| `morgan` logging | Provides audit trail (can be piped to a logging service). |
| `authenticate` middleware (JWT) | Enforces authentication and can be extended for role‑based access. |
| Input validation (`express-validator`) on `/login` | Demonstrates defense‑in‑depth against injection and malformed data. |
| Global error handler that hides stack traces in production | Reduces information disclosure (OWASP A03). |
| `express.json()` parser & body sanitisation (`normalizeEmail`, `trim`) | Guarantees a predictable request shape, protecting downstream code. |
| Comments indicating where to use **parameterised queries** & **bcrypt** | Future‑proof guidance for developers adding DB access. |

