## 3️⃣  Example – Full “secure config” module (Production‑ready)

Create `config/index.js` and replace direct `process.env` access throughout the codebase.

```js
// config/index.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

/**
 * Load configuration values.
 *
 *   • In development (`NODE_ENV !== 'production'`) we read from a .env file
 *     (populated by `dotenv` in the entry point).
 *
 *   • In production we fetch the secret from AWS Secrets Manager.
 *
 *   • All values are cached after the first fetch to avoid repeated network calls.
 */
class Config {
  constructor() {
    this.cache = {};
    // Detect production mode once
    this.isProd = process.env.NODE_ENV === 'production';
    if (!this.isProd) {
      // Load .env for local work
      require('dotenv').config({ path: '.env' });
    }
    this.secretsClient = this.isProd
      ? new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' })
      : null;
  }

  /**
   * Retrieve a config entry.
   * @param {string} name The env‑var name (e.g., 'JWT_SECRET')
   * @returns {Promise<string>}
   */
  async get(name) {
    // 1️⃣ Return cached value if we already fetched it.
    if (this.cache[name]) return this.cache[name];

    // 2️⃣ Development – read directly from process.env
    if (!this.isProd) {
      const value = process.env[name];
      if (!value) throw new Error(`Missing dev config: ${name}`);
      this.cache[name] = value;
      return value;
    }

    // 3️⃣ Production – fetch from Secrets Manager
    const command = new GetSecretValueCommand({ SecretId: name });
    const resp = await this.secretsClient.send(command);
    if (!resp.SecretString) throw new Error(`Secret ${name} returned no string`);
    const parsed = (() => {
      try {
        return JSON.parse(resp.SecretString);
      } catch {
        return resp.SecretString; // plain string secret
      }
    })();

    const value = typeof parsed === 'object' ? parsed[name] : parsed;
    if (!value) throw new Error(`Secret ${name} missing key ${name}`);
    this.cache[name] = value;
    return value;
  }
}

module.exports = new Config();
```

**Usage in `app.js`**

```js
const config = require('./config');

// Early bootstrap – we need the JWT secret for the auth middleware
(async () => {
  const JWT_SECRET = await config.get('JWT_SECRET');   // throws if missing
  // Pass JWT_SECRET into the authentication middleware (see earlier example)
  // Continue with server start…
})();
```

*Benefits*

* **Zero plaintext secrets in the repository** – they live in the cloud secret store.  
* **IAM‑based access control** – only the role attached to the container/instance can read them.  
* **Automatic rotation** – you can rotate the secret in the manager without redeploying code; the next request will fetch the fresh value (or you can invalidate the cache on a SIGUSR2).  
* **Clear separation of dev vs prod** – developers still get a convenient `.env` file, but production never touches the filesystem for secrets.

