## 2. Concrete Code Recommendations

Below is a *patch* that adds the most important security hardening measures while preserving the existing behaviour. Feel free to copy‑paste the updated `app.js` (or split the configuration into a `server.js`/`config.js` file if you prefer).

```javascript
// ─────────────────────────────────────────────────────────────────────────────
//  app.js – Secure baseline for an Express API
// ─────────────────────────────────────────────────────────────────────────────

require('dotenv').config();                 // 1️⃣ Load env vars (port, etc.)

const express = require('express');
const helmet = require('helmet');           // 2️⃣ Secure HTTP headers
const cors = require('cors');               // 3️⃣ Controlled CORS
const rateLimit = require('express-rate-limit'); // 4️⃣ Basic DoS mitigation
const morgan = require('morgan');           // 5️⃣ Request logging
const xss = require('xss');                 // 6️⃣ Optional content sanitiser (demo)

const app = express();

// ---------------------------------------------------------------------------
// 1. Global middleware (security + observability)
// ---------------------------------------------------------------------------

// Hide "X-Powered-By: Express"
app.disable('x-powered-by');

// Helmet adds a set of well‑known security headers:
//   Content‑Security‑Policy, Referrer‑Policy, X‑Content‑Type‑Options, etc.
app.use(helmet());

// Enable CORS only for trusted origins (change to your front‑end domain)
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://my‑trusted‑client.example.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  credentials: true,
}));

// Rate limiter – 100 requests per 15‑minute window per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(limiter);

// Body parser (if you add POST/PUT routes later)
app.use(express.json());

// Request logging – use 'combined' format in production, 'dev' locally
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// ---------------------------------------------------------------------------
// 2. Routes (unchanged behaviour, but with minimal hardening)
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  // No user input, so no sanitisation needed.
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Example of *not* exposing sensitive PII – only id & name.
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  // If you ever echo user‑provided data, run it through an XSS filter:
  // const safe = users.map(u => ({ ...u, name: xss(u.name) }));
  res.json(users);
});

// ---------------------------------------------------------------------------
// 3. Centralised error handling (captures async errors, logs, hides stack)
// ---------------------------------------------------------------------------

app.use((err, req, res, next) => {
  // Log the full error stack only in non‑production environments
  if (process.env.NODE_ENV !== 'production') {
    console.error(err);
  } else {
    // Production: log to a file / external service (e.g., Winston, Bunyan)
    // logger.error(err.message);
  }

  // Do **not** leak internal details to the client
  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
  });
});

// ---------------------------------------------------------------------------
// 4. Server bootstrap – use environment variable or fallback to 3000
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  // If you run behind a reverse proxy (NGINX, Cloudflare, etc.) you may
  // want to indicate you are listening on the *internal* port only.
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What changed and why?

| Change | Security purpose |
|--------|------------------|
| `require('dotenv').config()` | Keeps secret configuration out of source code (credentials, ports, CORS origins). |
| `helmet` | Sets a comprehensive set of HTTP security headers (prevents click‑jacking, MIME‑sniffing, etc.). |
| `cors` with a whitelist | Prevents browsers from making unwanted cross‑origin requests. |
| `express-rate-limit` | Simple mitigation against brute‑force and denial‑of‑service attacks. |
| `app.disable('x-powered-by')` | Removes the framework fingerprint from responses. |
| `morgan` logger | Gives you request audit trails for detection/forensics. |
| Central error handler | Guarantees that stack traces are never sent to the client (information leakage). |
| Reduced user payload (`/users` endpoint) | Stops accidental exposure of e‑mail addresses (PII). |
| `express.json()` & placeholder for `xss` | Pre‑pares the app for safe handling of JSON bodies and user‑generated strings. |
| Port driven by `process.env.PORT` | Allows the app to run in containers or managed platforms without hard‑coding the port. |

