### 2️⃣ GCP Secret Manager

```js
// secret-loader-gcp.js ----------------------------------------------------
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function loadGcpSecrets(secretId) {
  const [version] = await client.accessSecretVersion({
    name: `${secretId}/versions/latest`,
  });
  const payload = version.payload.data.toString('utf8');
  const secretObj = JSON.parse(payload);
  Object.entries(secretObj).forEach(([k, v]) => {
    if (!process.env[k]) process.env[k] = v;
  });
}
module.exports = { loadGcpSecrets };
```

Usage is analogous to the AWS example; just swap the import and call `loadGcpSecrets('projects/PROJECT_ID/secrets/my-app')`.

