## Example **final `app.js`** with AWS Secrets Manager integration

```js
// ------------------------------------------------------------
// app.js – Production‑ready entry point (AWS example)
// ------------------------------------------------------------

require('dotenv').config();          // optional, for local dev only
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const { loadAwsSecrets } = require('./secret-loader'); // <-- secret loader

// ------------------------------------------------------------
// 1️⃣ Load secrets *before* anything else runs
// ------------------------------------------------------------
(async () => {
  try {
    // Name of the secret in AWS Secrets Manager (JSON map)
    const secretName = process.env.AWS_SECRETS_NAME || 'my-app-prod-secrets';
    await loadAwsSecrets(secretName);
    // Verify that mandatory vars are present
    const mustHave = ['JWT_SECRET', 'DATABASE_URL'];
    mustHave.forEach(k => {
      if (!process.env[k]) throw new Error(`Missing required env var ${k}`);
    });
    // All good – bootstrap the server
    startServer();
  } catch (err) {
    console.error('🔒 Failed to initialise secrets:', err);
    process.exit(1);
  }
})();

// ------------------------------------------------------------
// 2️⃣ Server bootstrap (run only after secrets are ready)
// ------------------------------------------------------------
function startServer() {
  const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
  const app = express();

  // -------------------------------------------------------------------------
  // Security‑by‑default middleware
  // -------------------------------------------------------------------------
  app.use(helmet());

  // CSP – tighten as needed for your front‑end
  app.use(
    helmet.contentSecurityPolicy({
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'"],
        imgSrc: ["'self'"],
        connectSrc: ["'self'"],
      },
    })
  );

  // CORS (customise allowed origins)
  app.use(
    cors({
      origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
      methods: ['GET', 'POST', 'PUT', 'DELETE'],
    })
  );

  // Rate limiting – feel free to specialise per route later
  app.use(
    rateLimit({
      windowMs: 15 * 60 * 1000,
      max: 100,
      standardHeaders: true,
      legacyHeaders: false,
    })
  );

  // Request logging (structured, no secret data)
  app.use((req, res, next) => {
    logger.info({ method: req.method, url: req.originalUrl, ip: req.ip });
    next();
  });

  // -------------------------------------------------------------------------
  // Auth & role middleware (JWT based)
  // -------------------------------------------------------------------------
  const { authenticate, requireAdmin } = require('./security-middleware');

  // -------------------------------------------------------------------------
  // Routes
  // -------------------------------------------------------------------------
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // Protected endpoint – only admin can list users
  app.get('/users', authenticate, requireAdmin, (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // -------------------------------------------------------------------------
  // Central error handler (must be after all routes)
  // -------------------------------------------------------------------------
  app.use((err, _req, res, _next) => {
    logger.error(err);
    res.status(500).json({ error: 'Internal server error' });
  });

  // -------------------------------------------------------------------------
  // Server start
  // -------------------------------------------------------------------------
  const HOST = process.env.HOST || '127.0.0.1';
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, HOST, () => {
    logger.info(`🚀 Server listening on http://${HOST}:${PORT}`);
    logger.info('✅ Secrets successfully loaded from AWS Secrets Manager');
  });
}
```

### What changed?

| Change | Reason |
|--------|--------|
| **`loadAwsSecrets()` before app creation** | Guarantees *all* required secrets are present *prior* to any request handling. |
| **Explicit `mustHave` check** | Fails fast if a critical secret (e.g., `JWT_SECRET`) is missing. |
| **Removal of any hard‑coded secret files** | Eliminates the risk of committing credentials. |
| **`require('dotenv').config()` only for local dev** | Keeps the production path clean while still allowing developers to create a personal `.env` file that is never committed. |
| **`process.env.AWS_SECRETS_NAME`** | Makes the secret name configurable per environment (dev / staging / prod). |
| **Logging of “Secrets loaded” (no values)** | Provides visibility in logs without leaking the actual secret data. |

