  algorithms: ['HS256'],
});

// Protect the /users endpoint
app.get('/users', auth, (req, res) => {
  // now req.user contains the decoded JWT payload
  res.json([
    { id: 1, name: 'Alice' }, // omit email or limit fields based on role
    { id: 2, name: 'Bob' },
  ]);
});
```

If you want role‑based data filtering:

```js
