  secret: process.env.JWT_SECRET || 'CHANGE_ME_TO_A_SECURE_RANDOM_STRING',
  algorithms: ['HS256'],
});

// -------------------- Routes --------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Public health endpoint – no auth needed.
 * The /users endpoint is *protected* – only authenticated callers may see it.
 * Emails are hidden unless the user has the 'admin' role.
 */
app.get('/users', auth, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ];

  // Example role‑based field filtering
  const result = req.user && req.user.role === 'admin'
    ? users
    : users.map(u => ({ id: u.id, name: u.name })); // hide email for non‑admins

  res.json(result);
});

// -------------------- Error Handling --------------------
app.use((err, req, res, next) => {
  console.error(err); // Consider sending to a centralized log service
  const status = err.status || 500;
  const payload = process.env.NODE_ENV === 'production'
    ? { error: 'Internal server error' }
    : { error: err.message, stack: err.stack };
  res.status(status).json(payload);
});

// -------------------- Server Bootstrap --------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

