  // Loads .env only for local development; never in prod.
  require('dotenv').config();
}

// Pull secrets from a proper secret manager in prod.
// Example (AWS Secrets Manager) – replace with your platform.
async function loadSecrets() {
  if (process.env.NODE_ENV === 'production') {
    const AWS = require('aws-sdk');
    const sm = new AWS.SecretsManager();
    const secret = await sm.getSecretValue({ SecretId: 'myApp/jwt' }).promise();
    const parsed = JSON.parse(secret.SecretString);
    return { JWT_SECRET: parsed.jwtSecret };
  }
  // Dev fallback to .env
  return { JWT_SECRET: process.env.JWT_SECRET };
}

// Export a promise that resolves to the config values.
module.exports = loadSecrets();
```

Then, wherever you need the secret:

```js
