  // You can also add role‑based checks:
  // if (req.auth.role !== 'admin') return res.sendStatus(403);
  res.json([...]);
});
```

If you only need a quick “internal‑service” protection, consider **API‑key** validation or **mutual TLS**.

### 2.5. Rate Limiting & DoS Mitigation (A05)
Add **express‑rate‑limit** to throttle abusive clients.

```bash
npm i express-rate-limit
```

```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' }
});

app.use('/users', apiLimiter); // apply only to sensitive routes
```

### 2.6. Logging, Error Handling & Monitoring (A09)
Integrate a structured logger (e.g., **pino** or **winston**) and a global error handler.

```bash
npm i pino-http
```

```js
const logger = require('pino-http')();
app.use(logger); // logs each request with method, url, status, latency

// Centralized error handler
app.use((err, req, res, next) => {
  console.error(err);                // still log stack trace to console / log system
  res.status(err.status || 500).json({ error: err.message || 'Internal Server Error' });
});
```

For production you can pipe logs to a log‑aggregation service (ELK, Splunk, etc.) and set up alerts for anomalous response codes.

