## 2. Recommended hardening steps (with code)

### 2.1. Add essential security middleware

```js
// ---- 0️⃣  Install dependencies ------------------------------------------------
// npm i helmet cors express-rate-limit hpp xss-clean dotenv morgan

// ---- 1️⃣  Load env variables ---------------------------------------------------
require('dotenv').config();   // keep secrets out of source control

// ---- 2️⃣  Import core modules --------------------------------------------------
const express = require('express');
const helmet = require('helmet');           // security headers
const cors   = require('cors');             // control origins
const rateLimit = require('express-rate-limit'); // DoS mitigation
const hpp    = require('hpp');               // HTTP Parameter Pollution protection
const xss    = require('xss-clean');         // basic XSS sanitisation
const morgan = require('morgan');           // request logging
```

**Why?**  
* `helmet` adds dozens of HTTP headers (CSP, HSTS, X‑Frame‑Options, etc.).  
* `cors` limits which origins can call your API.  
* `express-rate-limit` thwarts brute‑force and simple DoS attacks.  
* `hpp` prevents attackers from smuggling multiple parameters with the same name.  
* `xss-clean` sanitises user‑submitted data to stop reflected XSS.  
* `morgan` creates an audit trail (A10).

### 2.2. Global middleware configuration

```js
const app = express();

// Body parsing (JSON & URL‑encoded) – required before validation
app.use(express.json({ limit: '10kb' }));          // limit payload size
app.use(express.urlencoded({ extended: false }));

// Security middleware stack (order matters)
app.use(helmet());                // add secure headers
app.use(cors({                    // allow only trusted origins
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET','POST','PUT','DELETE'],
}));
// Prevent HTTP Parameter Pollution
app.use(hpp());
// Basic XSS sanitisation (only works on body, query, params)
app.use(xss());
// Rate limiting – 100 requests per 15 min per IP (adjust as needed)
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
}));

// Request logging (combined format) – logs to stdout (can pipe to a file or SIEM)
app.use(morgan('combined'));
```

**Result:** Every request now passes through a hardened security pipeline before hitting your routes.

### 2.3. Centralised error handling & hide stack traces

```js
// Catch‑all error handler (should be after all routes)
app.use((err, req, res, next) => {
  // Log the error details (never expose to client)
  console.error(`[${new Date().toISOString()}]`, err);

  // Send generic message; avoid leaking stack traces in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;   // in dev you may want the original message

  res.status(status).json({ error: message });
});
```

**Why?** Prevents accidental disclosure of implementation details (A5, A10).

### 2.4. Add authentication & authorization skeleton

For a production‑grade service you’ll likely choose **JWT** (stateless) or **session‑based** auth.  Here’s a minimal JWT example using `jsonwebtoken`.

```bash
npm i jsonwebtoken bcryptjs
```

```js
const jwt      = require('jsonwebtoken');
const bcrypt   = require('bcryptjs');

// ---- 3️⃣  Auth utilities ------------------------------------------------------
const JWT_SECRET = process.env.JWT_SECRET || 'changeme-very-secret';
const JWT_EXPIRES_IN = '1h';

// Middleware to protect routes
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;           // payload (e.g. { id, role })
    next();
  });
}
```

**Example protected endpoint**

```js
// GET /users – only authenticated users can view the list
app.get('/users', authenticateToken, (req, res) => {
  // In a real app, fetch from DB and enforce RBAC (role‑based access)
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]);
});
```

**Login route (illustrative)**

```js
// POST /login  (expects { email, password })
app.post('/login', async (req, res, next) => {
  try {
    const { email, password } = req.body;

    // ---- 4️⃣  Input validation (see next section) ----
    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    // Replace the demo user store with a real DB query
    const user = demoUsers.find(u => u.email === email);
    if (!user) return res.status(401).json({ error: 'Invalid credentials' });

    const passwordMatches = await bcrypt.compare(password, user.passwordHash);
    if (!passwordMatches) return res.status(401).json({ error: 'Invalid credentials' });

    const payload = { id: user.id, role: user.role };
    const token = jwt.sign(payload, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });
    res.json({ token });
  } catch (e) { next(e); }
});
```

> **Tip:** Store passwords with `bcrypt` (or `argon2`) hashed + salted. Never store plaintext.

### 2.5. Input validation & sanitisation (OWASP A1, A4)

`express-validator` is a lightweight, well‑maintained library.

```bash
npm i express-validator
```

```js
const { body, param, query, validationResult } = require('express-validator');

// Helper to return validation errors in a unified format
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(422).json({ errors: errors.array() });
  }
  next();
}

// Example: create a new user (POST /users)
app.post(
  '/users',
  authenticateToken,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be 2‑50 characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required'),
    body('password')
      .isStrongPassword({ // uses zxcvbn‑like defaults
        minLength: 8,
        minLowercase: 1,
        minUppercase: 1,
        minNumbers: 1,
        minSymbols: 1,
      })
      .withMessage('Password is too weak')
  ],
  validate,
  async (req, res, next) => {
    // Safe to trust req.body at this point
    const { name, email, password } = req.body;
    // …store in DB after bcrypt hashing
    res.status(201).json({ message: 'User created' });
  }
);
```

**Why?**  
* Guarantees that only expected, correctly‑typed data reaches the business logic (prevents NoSQL/SQL injection, prototype pollution, etc.).  
* Normalisation (`normalizeEmail`) stops crafted email tricks.  

### 2.6. Content Security Policy (CSP)

If you ever serve HTML, set CSP with `helmet`. Example:

```js
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", 'cdnjs.cloudflare.com'],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [], // forces HTTPS for sub‑resources
    },
  })
);
```

### 2.7. Enforce HTTPS & HSTS

When the app runs behind a reverse proxy (e.g., Nginx, AWS ELB), enable Express’s trust‑proxy setting and HSTS:

```js
app.set('trust proxy', 1); // trust first proxy
app.use(
  helmet.hsts({
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  })
);
```

**Note** – In development you may skip `trust proxy` or use a self‑signed cert.

### 2.8. CSRF protection for state‑changing routes

If you expose any browser‑based forms (POST/PUT/DELETE) with cookies‑based auth, add `csurf`.

```bash
npm i csurf
```

```js
const csurf = require('csurf');
const csrfProtection = csurf({ cookie: true });

app.use(csrfProtection);

// Example route exposing the token to the client (e.g., SPA bootstrap)
app.get('/csrf-token', (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});
```

If you stay with pure JWT + `Authorization: Bearer` header, CSRF is not needed because the token isn’t automatically submitted by browsers.

### 2.9. Secure dependency management (OWASP A9)

1. **Pin exact versions** in `package.json` (no `^` or `*`).  
2. Run `npm audit` regularly and fix with `npm audit fix`.  
3. Add a CI step that fails the build on known vulnerabilities.  

Example `scripts` entry:

```json
"scripts": {
  "start": "node app.js",
  "test": "npm run lint && npm run security",
  "lint": "eslint .",
  "security": "npm audit --audit-level=high"
}
```

### 2.10. Logging & monitoring (OWASP A10)

* Use a structured logger (e.g., `pino` or `winston`) instead of plain `console.log`.  
* Log **who** performed an action, **what** they attempted, **when**, and **outcome**.  
* Send logs to a centralized SIEM or at least to a file that rotates (`logrotate`).  

```bash
npm i pino
```

```js
const pino = require('pino');
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

app.use((req, res, next) => {
  logger.info({ method: req.method, url: req.originalUrl, ip: req.ip });
  next();
});
```

